const (
	// Expire the JWT in just less than 10 minutes to account for drift across servers,
	// because the setting on dotcom is 10 minutes and we've gotten some errors that say
	// `Expiration time' claim ('exp') is too far in the future` (from integration_assertion.rb)
	jwtExpiryTime = (time.Minute * 10) - (time.Second * 10)

	// Enables retries with exponential backoff when calling: /app/global/access_tokens API
	// https://github.com/github/actions-relaunch/issues/700
	// Goes here instead of featureflags to avoid cyclical dependency import
	TokenRequestsRetriesWithBackoff = "retries_with_exp_backoff_for_access_tokens_minting"
)

// Service provides an interface for making requests to obtain installation access tokens.
type Service interface {
	// ReadTokenForSiteScopedInstallation returns a token with read permissions for the given repos within an org
	ReadTokenForSiteScopedInstallation(ctx context.Context, ownerID int64, repositories []string, isPackageFlow bool) (*AccessToken, error)

	// SiteScopedTokenForRepositoryOwner returns a site scoped token for a given repository owner
	SiteScopedTokenForRepositoryOwner(ctx context.Context, repositoryID types.GlobalID, ownerID int64, useCache bool, perms *InstallationPermissions, extendedPerms *ExtendedPermissions) (*AccessToken, error)

	// SiteScopedTokenForRepository returns a site scoped token for a given repository
	SiteScopedTokenForRepository(ctx context.Context, repositoryID types.GlobalID, ownerID int64, useCache bool, perms *InstallationPermissions, extendedPerms *ExtendedPermissions) (*AccessToken, error)

	// RefreshToken calls the API to extend the lifetime of the supplied Access Token
	RefreshToken(ctx context.Context, token *AccessToken) (*AccessToken, error)

	// RevokeToken calls the API to revoke the Access Token
	RevokeToken(ctx context.Context, repositoryID types.GlobalID, token *AccessToken) error
}

type service struct {
	base                 *url.URL
	obs                  *observability.Observability
	appID                int64
	appPrivateKey        *rsa.PrivateKey
	clock                clock.Clock
	http                 *httpclient.Client
	env                  launchconfig.AppEnv
	ghCache              launchcache.GitHubCache
	actorFFChecker       func(context.Context, string, types.GlobalID) bool
	globalFFChecker      func(context.Context, string) bool
	getRepositoryOwnerID func(ctx context.Context, repoID int64, useCache bool) (int64, error)
	breaker              *circuit.Breaker
	isMultiTenant        bool
}

type PullRequestInstallationPermissions struct {
	// CodeQL file format. This permission allows fork PRs without write access to still be scanned by CodeQL.
	Sarifs InstallationPermissionAccess `json:"sarifs,omitempty"`
}

type PerPullRequestPermissions struct {
	Number      int                                `json:"number,omitempty"`
	Permissions PullRequestInstallationPermissions `json:"permissions,omitempty"`
}

type PerWorkflowRunPermissions struct {
	ID          int64                               `json:"id,omitempty"`
	Permissions *WorkflowRunInstallationPermissions `json:"permissions,omitempty"`
}

type WorkflowRunInstallationPermissions struct {
	// Codespaces Prebuilds. This permission allows a run to create a Codespaces prebuild template.
	CodespacesPrebuild InstallationPermissionAccess `json:"codespaces_prebuild,omitempty"`
}

// Valid returns true if all permissions for the workflow run are valid
func (wri *WorkflowRunInstallationPermissions) Valid() bool {
	return wri.CodespacesPrebuild == WriteAccess
}

// ExtendedPermissions is optionally stored in DB for tokens generated by access_tokens/scoped
type ExtendedPermissions struct {
	PerPullRequestPermissions *PerPullRequestPermissions `json:"pull_request,omitempty"`
	PerWorkflowRunPermissions *PerWorkflowRunPermissions `json:"workflow_run,omitempty"`
}

func (ep *ExtendedPermissions) String() string {
	if ep == nil {
		return "<nil>"
	}

	var (
		prPermissions = "<nil>"
		wrPermissions = "<nil>"
	)
	if ep.PerPullRequestPermissions != nil {
		prPermissions = fmt.Sprintf("{Number: %d, Permissions: %+v}", ep.PerPullRequestPermissions.Number, ep.PerPullRequestPermissions.Permissions)
	}

	if ep.PerWorkflowRunPermissions != nil {
		var wrperms WorkflowRunInstallationPermissions
		if ep.PerWorkflowRunPermissions.Permissions != nil {
			wrperms = *ep.PerWorkflowRunPermissions.Permissions
		}
		wrPermissions = fmt.Sprintf("{ID: %d, Permissions: %+v}", ep.PerWorkflowRunPermissions.ID, wrperms)
	}

	return fmt.Sprintf("{PerPullRequestPermissions: %s, PerWorkflowRunPermissions: %s}", prPermissions, wrPermissions)
}

type ScopedInstallationToken struct {
	Token        string                   `json:"token"`
	ExpiresAt    *time.Time               `json:"expires_at,omitempty"`
	Permissions  *InstallationPermissions `json:"permissions,omitempty"`
	Repositories *[]gogithub.Repository   `json:"repositories,omitempty"`
	ValidAfter   *time.Time               `json:"valid_after,omitempty"`
}

type InstallationPermissionAccess string

const ReadAccess InstallationPermissionAccess = "read"
const WriteAccess InstallationPermissionAccess = "write"
const NoneAccess InstallationPermissionAccess = "none"

type InstallationPermissions struct {
	Actions            InstallationPermissionAccess `json:"actions,omitempty"`
	Attestations       InstallationPermissionAccess `json:"attestations,omitempty"`
	Checks             InstallationPermissionAccess `json:"checks,omitempty"`
	Contents           InstallationPermissionAccess `json:"contents,omitempty"`
	Deployments        InstallationPermissionAccess `json:"deployments,omitempty"`
	Discussions        InstallationPermissionAccess `json:"discussions,omitempty"`
	Issues             InstallationPermissionAccess `json:"issues,omitempty"`
	Metadata           InstallationPermissionAccess `json:"metadata,omitempty"`
	Packages           InstallationPermissionAccess `json:"packages,omitempty"`
	Pages              InstallationPermissionAccess `json:"pages,omitempty"`
	PullRequests       InstallationPermissionAccess `json:"pull_requests,omitempty"`
	RepositoryProjects InstallationPermissionAccess `json:"repository_projects,omitempty"`
	Statuses           InstallationPermissionAccess `json:"statuses,omitempty"`
	SecurityEvents     InstallationPermissionAccess `json:"security_events,omitempty"`
}

type PermissionSettings struct {
	// The InstallationPermissions are "embedded" for deserialization backwards-compatibility with existing runs
	InstallationPermissions

	ExtendedPermissions *ExtendedPermissions `json:"extended_permissions,omitempty"`
	DefaultPermissions  TokenPermissionSet   `json:"default_permissions,omitempty"`
}

// MergeMinimum Merge two token installation permissions based on the minimum access level exclude extended_permission.
func (i *InstallationPermissions) MergeMinimum(base *InstallationPermissions) error {
	if base == nil {
		return errors.Errorf("compared InstallationPermissions object is nil")
	}
	i.Actions = min(i.Actions, base.Actions)
	i.Attestations = min(i.Attestations, base.Attestations)
	i.Checks = min(i.Checks, base.Checks)
	i.Contents = min(i.Contents, base.Contents)
	i.Deployments = min(i.Deployments, base.Deployments)
	i.Discussions = min(i.Discussions, base.Discussions)
	i.Issues = min(i.Issues, base.Issues)
	i.Metadata = min(i.Metadata, base.Metadata)
	i.Packages = min(i.Packages, base.Packages)
	i.Pages = min(i.Pages, base.Pages)
	i.PullRequests = min(i.PullRequests, base.PullRequests)
	i.RepositoryProjects = min(i.RepositoryProjects, base.RepositoryProjects)
	i.Statuses = min(i.Statuses, base.Statuses)
	i.SecurityEvents = min(i.SecurityEvents, base.SecurityEvents)
	return nil
}

func min(x InstallationPermissionAccess, y InstallationPermissionAccess) InstallationPermissionAccess {
	if x == "" || x == NoneAccess || y == "" || y == NoneAccess {
		return ""
	}
	if x == ReadAccess || y == ReadAccess {
		return ReadAccess
	}
	return WriteAccess
}

type refreshScopedInstallationTokenRequest struct {
	Token string `json:"token,omitempty"`
}

// Value serializes for database.
func (i InstallationPermissions) Value() (driver.Value, error) {
	b, err := json.Marshal(&i)
	return string(b), err
}

// Scan reads from database.
func (i *InstallationPermissions) Scan(val any) error {
	switch v := val.(type) {
	case string:
		return json.Unmarshal([]byte(v), i)
	case []byte:
		return json.Unmarshal(v, i)
	default:
		return fmt.Errorf("scan: unable to scan type %T into InstallationPermissions", val)
	}
}

// Value serializes for database.
func (i PermissionSettings) Value() (driver.Value, error) {
	b, err := json.Marshal(&i)
	return string(b), err
}

// Scan reads from database.
func (i *PermissionSettings) Scan(val any) error {
	var err error
	switch v := val.(type) {
	case string:
		err = json.Unmarshal([]byte(v), i)
	case []byte:
		err = json.Unmarshal(v, i)
	default:
		err = fmt.Errorf("scan: unable to scan type %T into PermissionSettings", val)
	}

	if err == nil && i.DefaultPermissions == "" {
		// Back-compat for workflows started before DefaultPermissions was added.
		// Do not remove. Otherwise in-progress runs on GHES will fail after upgrade.
		if i.InstallationPermissions.Contents == WriteAccess {
			i.DefaultPermissions = WritePermissions
		} else {
			i.DefaultPermissions = ReadPermissions
		}
	}

	return err
}

// NewService returns a service for obtaining installation access tokens from GitHub.
func NewService(
	env launchconfig.AppEnv,
	obs *observability.Observability,
	baseURL *url.URL,
	appID int64,
	appPrivateKey []byte,
	breaker *circuit.Breaker,
	http *httpclient.Client,
	cache launchcache.GitHubCache,
	actorFFChecker func(context.Context, string, types.GlobalID) bool,
	globalFFChecker func(context.Context, string) bool,
	getRepositoryOwnerID func(context.Context, int64, bool) (int64, error),
	hooks *httpclient.ClientHooks,
	isMultiTenant bool,
) (*service, error) {
	return newService(env, obs, baseURL, appID, appPrivateKey, clock.New(), breaker, http, cache, actorFFChecker, globalFFChecker, getRepositoryOwnerID, hooks, isMultiTenant)
}

// This exists so that tests can customize the clock.
func newService(
	env launchconfig.AppEnv,
	obs *observability.Observability,
	baseURL *url.URL,
	appID int64,
	appPrivateKey []byte,
	c clock.Clock,
	breaker *circuit.Breaker,
	http *httpclient.Client,
	cache launchcache.GitHubCache,
	actorFFChecker func(context.Context, string, types.GlobalID) bool,
	globalFFChecker func(context.Context, string) bool,
	getRepositoryOwnerID func(context.Context, int64, bool) (int64, error),
	hooks *httpclient.ClientHooks,
	isMultiTenant bool,
) (*service, error) {

	if len(baseURL.Path) > 0 && !strings.HasSuffix(baseURL.Path, "/") {
		// In the case of enterprise, we prefix the paths with something like
		// /v3/api/, however, to avoid some unfortunate behavior with
		// Golang's url.Parse method, we need to ensure that this path
		// terminates with a slash. We could guess and assume that we should
		// append a slash, but in the event that we meet these conditions,
		// it may be safest to simply make the error clear so that we can
		// fix the API_V3_PATH configuration value itself.
		// See https://go.dev/play/p/5LCH7FHIGnk
		return nil, errors.New("github base url must end with slash if using a path prefix: " + baseURL.Path)
	}

	appPrivateKey = utils.UnescapeConsulKVBytes(appPrivateKey)

	pk, err := jwt.ParseRSAPrivateKeyFromPEM(appPrivateKey)
	if err != nil {
		return nil, errors.Wrap(err, "failed to parse github app private key")
	}

	http = http.WithHooks(hooks)
	http = http.WithSvcName("gh-token")

	s := &service{
		breaker:              breaker,
		base:                 baseURL,
		appID:                appID,
		appPrivateKey:        pk,
		clock:                c,
		obs:                  obs,
		http:                 http,
		env:                  env,
		ghCache:              cache,
		actorFFChecker:       actorFFChecker,
		globalFFChecker:      globalFFChecker,
		getRepositoryOwnerID: getRepositoryOwnerID,
		isMultiTenant:        isMultiTenant,
	}

	return s, nil
}

func (s *service) jwtBearerToken() (string, error) {
	issuedAt := time.Now().Unix()
	claims := &jwt.RegisteredClaims{
		IssuedAt:  &jwt.NumericDate{Time: time.Unix(issuedAt, 0)},
		ExpiresAt: &jwt.NumericDate{Time: time.Unix(issuedAt+int64(jwtExpiryTime.Seconds()), 0)},
		Issuer:    strconv.FormatInt(s.appID, 10),
	}
	token := jwt.NewWithClaims(jwt.SigningMethodRS256, claims)
	return token.SignedString(s.appPrivateKey)
}

// SiteScopedTokenForRepositoryOwner creates a site scoped token scoped to the repository owner
func (s *service) SiteScopedTokenForRepositoryOwner(ctx context.Context, repositoryID types.GlobalID, ownerID int64, useCache bool, perms *InstallationPermissions, extendedPerms *ExtendedPermissions) (*AccessToken, error) {
	return s.createSiteScopedToken(ctx, repositoryID, ownerID, useCache, false, perms, extendedPerms)
}

// SiteScopedTokenForRepository creates a site scoped token scoped to the repository
func (s *service) SiteScopedTokenForRepository(ctx context.Context, repositoryID types.GlobalID, ownerID int64, useCache bool, perms *InstallationPermissions, extendedPerms *ExtendedPermissions) (*AccessToken, error) {
	return s.createSiteScopedToken(ctx, repositoryID, ownerID, useCache, true, perms, extendedPerms)
}

func (s *service) createSiteScopedToken(ctx context.Context, repositoryID types.GlobalID, ownerID int64, useCache, scopeToRepo bool, perms *InstallationPermissions, extendedPerms *ExtendedPermissions) (*AccessToken, error) {
	ctx, span := tracing.Start(ctx)
	defer span.End()

	repoID, err := s.getDatabaseIDFromGlobalID(repositoryID)
	if err != nil {
		return nil, tracing.RecordError(span, err)
	}

	if ownerID == 0 {
		s.obs.Debug(ctx, "Owner id not given, retrieve from dotcom")

		// Attempt to fetch the owner ID for the repository using the Twirp cache
		ownerID, err = s.getRepositoryOwnerID(ctx, repoID, true)
		if err != nil {
			return nil, tracing.RecordError(span, errors.Wrap(err, "could not find owner id by repository id"))
		}
	}

	repos := []int64{}
	if scopeToRepo {
		repos = []int64{repoID}
	}

	siteScopedTokenReq := siteScopedTokenBody{
		TargetID:      ownerID,
		RepositoryIDs: repos,
		Permissions:   perms,
	}

	if extendedPerms != nil {
		extendedPermissionsForPRsAndWorkflowRuns := make([]repoExtendedPermissions, 0, len(repos))
		for _, repoID := range repos {
			repoExtendedPermissions := repoExtendedPermissions{RepositoryID: repoID}
			if extendedPerms.PerPullRequestPermissions != nil {
				repoExtendedPermissions.PullRequests = []PerPullRequestPermissions{*extendedPerms.PerPullRequestPermissions}
			}
			if extendedPerms.PerWorkflowRunPermissions != nil {
				repoExtendedPermissions.WorkflowRuns = []PerWorkflowRunPermissions{*extendedPerms.PerWorkflowRunPermissions}
			}

			extendedPermissionsForPRsAndWorkflowRuns = append(extendedPermissionsForPRsAndWorkflowRuns, repoExtendedPermissions)
		}

		siteScopedTokenReq.ExtendedPermissions = extendedPermissionsForPRsAndWorkflowRuns
	}

	token, err := s.createSiteScopedInstallationToken(ctx, useCache, siteScopedTokenReq)
	if err != nil {
		if httpErr := errtypes.GetHTTPError(err); httpErr != nil {
			// 404 means the user/target cannot be found, 422 could mean that the owner doesn't own
			// the repository or the user/repo is malformed. In any case, try to fetch the owner and try again
			// in order to successfully complete the requested operation.
			if httpErr.MatchStatusCodes(http.StatusNotFound, http.StatusUnprocessableEntity) {
				s.obs.Debug(ctx, "Received 404 or 422 when getting token, falling back to fetching the owner id")

				// Fetch the owner ID without using the Twirp cache
				ownerID, err := s.getRepositoryOwnerID(ctx, repoID, false)
				if err != nil {
					return nil, tracing.RecordError(span, errors.Wrap(err, "could not find owner id by repository id"))
				}
				siteScopedTokenReq.TargetID = ownerID

				return s.createSiteScopedInstallationToken(ctx, useCache, siteScopedTokenReq)
			}
		}
	}

	return token, err
}

func fractionOfDuration(dur time.Duration, percent int64) time.Duration {
	// scaling by `percent` before dividing by 100 to avoid truncation by integer rounding
	return (dur * time.Duration(percent)) / 100
}

func (s *service) RefreshToken(ctx context.Context, token *AccessToken) (*AccessToken, error) {
	token, _, err := s.refreshToken(ctx, token)

	return token, err
}

func (s *service) RevokeToken(ctx context.Context, repositoryID types.GlobalID, token *AccessToken) error {
	ctx, span := tracing.Start(ctx)
	defer span.End()
	opName := "RevokeToken"

	_, err := s.getDatabaseIDFromGlobalID(repositoryID)
	if err != nil {
		return tracing.RecordError(span, err)
	}

	validator := func(resp *http.Response) (retryable bool, err error) {
		// 204 means token revoke successfully
		// 401 means token already expired or revoked
		if resp.StatusCode != http.StatusNoContent && resp.StatusCode != http.StatusUnauthorized {
			return false, errtypes.NewHTTPError(resp)
		}

		return false, nil
	}
	// Check for GitHub rate limit responses first
	validator = ratelimit.ResponseValidator(ctx, s.obs, opName, true, validator)

	opts := s.withDefaultOpts(validator, launchhttp.WithAccessToken(token.Token))

	url, err := s.appendURL("installation/token")
	if err != nil {
		return tracing.RecordError(span, err)
	}
	err = s.http.Do(ctx, opName, http.MethodDelete, url, nil, nil, opts...)
	if err != nil {
		return tracing.RecordError(span, errors.Wrap(err, "failed to revoke access token"))
	}

	return nil
}

func (s *service) refreshToken(ctx context.Context, token *AccessToken) (*AccessToken, time.Time, error) {
	ctx, span := tracing.Start(ctx)
	defer span.End()
	opName := "RefreshToken"

	tokenReq := refreshScopedInstallationTokenRequest{Token: token.Token}
	body, err := json.Marshal(tokenReq)
	if err != nil {
		return nil, time.Time{}, tracing.RecordError(span, err)
	}

	validator := func(resp *http.Response) (retryable bool, err error) {
		if resp.StatusCode < 200 || resp.StatusCode > 299 {
			httpError := errtypes.NewHTTPError(resp)
			if resp.StatusCode == http.StatusNotFound {
				// 404 means the installation token is no longer active (already expired)
				return false, errors.Wrap(httpError, "invalid installation token")
			}

			return resp.StatusCode >= http.StatusInternalServerError, err
		}

		return false, nil
	}
	// Check for GitHub rate limit responses first
	validator = ratelimit.ResponseValidator(ctx, s.obs, opName, false, validator)

	t, err := s.jwtBearerToken()
	if err != nil {
		return nil, time.Time{}, tracing.RecordError(span, err)
	}

	opts := s.withDefaultOpts(validator, launchhttp.WithBearerToken(t))

	url, err := s.appendURL("app/installation/access_tokens")
	if err != nil {
		return nil, time.Time{}, err
	}
	var sit *ScopedInstallationToken
	err = s.http.Do(ctx, opName, http.MethodPatch, url, body, &sit, opts...)
	if err != nil {
		return nil, time.Time{}, tracing.RecordError(span, errors.Wrap(err, "failed to request access token expiry update"))
	}

	var expiration time.Time
	if sit.ExpiresAt != nil {
		expiration = *sit.ExpiresAt
	}

	refreshedToken := &AccessToken{Token: sit.Token, Expiry: expiration}
	return refreshedToken, refreshedToken.Expiry, nil
}

// https://developer.github.com/changes/2016-09-14-Integrations-Early-Access/
const mediaTypeIntegrationPreview = "application/vnd.github.machine-man-preview+json"

// Get site scoped installation token with Read permissions for repos in 1 org
func (s *service) ReadTokenForSiteScopedInstallation(ctx context.Context, ownerID int64, repositories []string, isPackageFlow bool) (*AccessToken, error) {
	ctx, span := tracing.Start(ctx)
	defer span.End()
	if len(repositories) == 0 {
		return nil, tracing.RecordError(span, errors.New("no repositories provided"))
	}

	siteScopedTokenReq := siteScopedTokenBody{
		TargetID:     ownerID,
		Repositories: repositories,
		Permissions:  getReadPerms(isPackageFlow),
	}

	token, err := s.createSiteScopedInstallationToken(ctx, true, siteScopedTokenReq)
	if err != nil {
		return nil, tracing.RecordError(span, err)
	}

	return token, nil
}

func getReadPerms(isPackageFlow bool) *InstallationPermissions {
	if isPackageFlow {
		return &InstallationPermissions{
			Actions:  ReadAccess,
			Packages: ReadAccess,
		}
	}

	return &InstallationPermissions{
		Contents: ReadAccess,
		Metadata: ReadAccess,
		Actions:  ReadAccess,
	}
}

type siteScopedTokenBody struct {
	TargetID            int64                     `json:"target_id,omitempty"`
	RepoVisibility      string                    `json:"repo_visibility,omitempty"`
	RepositoryIDs       []int64                   `json:"repository_ids,omitempty"`
	Repositories        []string                  `json:"repositories,omitempty"`
	Permissions         *InstallationPermissions  `json:"permissions"`
	ExtendedPermissions []repoExtendedPermissions `json:"extended_permissions,omitempty"`
}

type repoExtendedPermissions struct {
	RepositoryID int64                       `json:"repository_id"`
	PullRequests []PerPullRequestPermissions `json:"pull_requests,omitempty"`
	WorkflowRuns []PerWorkflowRunPermissions `json:"workflow_runs,omitempty"`
}

func (s *service) createSiteScopedInstallationToken(ctx context.Context, useCache bool, siteScopedTokenReq siteScopedTokenBody) (*AccessToken, error) {
	ctx, span := tracing.Start(ctx)
	tags := statter.Tags{}
	defer func() {
		s.obs.Counter(ctx, "site_scoped.token.create", tags, 1)
		span.End()
	}()

	// Format request body
	body, err := json.Marshal(&siteScopedTokenReq)
	if err != nil {
		tags["error"] = strconv.FormatBool(true)
		return nil, errors.Wrap(err, "marshaling site scoped token body request to json")
	}

	// Check cache (if useCache is true)
	cache := s.ghCache.SiteScopedTokenCacheFor(s.appID, siteScopedTokenReq.TargetID, body)
	if useCache {
		jsonToken, ok, err := cache.Get(ctx)
		if err != nil {
			tags["cache_hit"] = strconv.FormatBool(false)
			tags["cache_error"] = strconv.FormatBool(true)
			s.obs.Report(ctx, errors.Wrap(err, "failed to look up cache"))
		} else if ok {
			tags["cache_hit"] = strconv.FormatBool(true)
			var tk AccessToken
			if err := json.Unmarshal(jsonToken, &tk); err != nil {
				s.obs.Report(ctx, errors.Wrap(err, "unmarshaling token from json for Get"))
			} else {
				return &tk, nil
			}
		}
		tags["cache_hit"] = strconv.FormatBool(false)
	}

	// Create token
	path := "app/global/access_tokens"

	it, _, err := s.createInstallationTokenCommon(ctx, body, path, "createSiteScopedInstallationTokenCommon")
	if err != nil {
		tags["error"] = strconv.FormatBool(true)
		return nil, tracing.RecordError(span, errors.Wrap(err, "creating site scoped installation token"))
	}
	if it.Token == "" {
		tags["error"] = strconv.FormatBool(true)
		return nil, errors.New("non-erroneous api call returned nil-token")
	}
	if it.ExpiresAt == nil {
		tags["error"] = strconv.FormatBool(true)
		return nil, errors.New("non-erroneous api call returned nil-expiry")
	}
	tags["error"] = strconv.FormatBool(false)

	token := &AccessToken{Token: it.Token, Expiry: *it.ExpiresAt, Permissions: *siteScopedTokenReq.Permissions, ValidAfter: it.ValidAfter}

	// Store token in cache
	jsonToken, err := json.Marshal(token)
	if err != nil {
		s.obs.Report(ctx, errors.Wrap(err, "marshaling token to json for Set"))
	} else {
		// Cache token for future use, for a bit less than expiry to be safe
		expiry := fractionOfDuration(time.Until(token.Expiry), 80)
		if err := cache.Set(ctx, jsonToken, expiry); err != nil {
			// log but don't fail
			s.obs.Report(ctx, errors.Wrap(err, "failed to write in cache"))
		}
	}

	return token, nil
}

func (s *service) createInstallationTokenCommon(ctx context.Context, body []byte, path string, funcName string) (*ScopedInstallationToken, time.Time, error) {
	tags := statter.Tags{}

	url, err := s.appendURL(path)
	if err != nil {
		return nil, time.Time{}, err
	}

	t, err := s.jwtBearerToken()
	if err != nil {
		return nil, time.Time{}, err
	}

	validator := func(resp *http.Response) (retryable bool, err error) {
		if resp.StatusCode < 200 || resp.StatusCode > 299 {
			// Sometimes we get a 422 response when creating tokens. The reason is returned in the body, so try
			// to read and log.
			if resp.StatusCode == http.StatusUnprocessableEntity {
				if body, err := io.ReadAll(resp.Body); err == nil {
					s.obs.Debug(ctx, "Received 422 when creating token", kvp.String("http.response.body", string(body)))
				}
			}

			// A 403 response while creating an installation token could indicate the Actions GitHub App as a whole is being rate limited.
			// This could impact all users. Log the body to see if it explains the nature of the 403 response.
			if resp.StatusCode == http.StatusForbidden {
				if body, err := io.ReadAll(resp.Body); err == nil {
					s.obs.Debug(ctx, "Received 403 when creating token",
						kvp.String("http.response.body", string(body)),
						kvp.String("http.response.headers.x_ratelimit_limit_header", resp.Header.Get("X-RateLimit-Limit")),
						kvp.String("http.response.headers.x_ratelimit_remaining_header", resp.Header.Get("X-RateLimit-Remaining")),
						kvp.String("http.response.headers.retry_after_header", resp.Header.Get("Retry-After")),
					)
				}
			}

			return resp.StatusCode >= http.StatusInternalServerError, errtypes.NewHTTPError(resp)
		}

		return false, nil
	}
	// Check for GitHub rate limit responses first
	validator = ratelimit.ResponseValidator(ctx, s.obs, funcName, false, validator)

	reqOpts := make([]launchhttp.RequestOption, 0)
	reqOpts = append(reqOpts, launchhttp.WithBearerToken(t))

	if s.isMultiTenant {
		tenantIDOpt := func(req *http.Request) error {
			return ghtenant.ForwardGitHubTenant(req, s.isMultiTenant, s.obs.Logger)
		}
		reqOpts = append(reqOpts, tenantIDOpt)
	}

	opts := s.withDefaultOpts(validator, reqOpts...)

	if s.globalFFChecker(ctx, TokenRequestsRetriesWithBackoff) {
		// This configuration will lead to retry schedule like this:
		// initial call | m=+0.014588830
		// call: 1 | m=+5.084014967
		// call: 2 | m=+10.851943417
		// call: 3 | m=+36.903689843as
		// This will override errorProcessor() and allow retries with backoff
		// with the paramters above
		opts = append(opts,
			httpclient.WithBackoff(
				3,             // RetriesMax
				5*time.Second, // RetryDelay
				2,             // RetryMultiplier
				1,             // RetriesRand
			),
			httpclient.WithRequestErrorProcessor(func(err error) error { return err }),
		)
		defer func() {
			s.obs.Counter(ctx, "create.installation_token_common.retries_w_backoff", tags, 1)
		}()
	}

	var sit *ScopedInstallationToken
	err = s.http.Do(ctx, funcName, http.MethodPost, url, body, &sit, opts...)
	if err != nil {
		wrappedError := errors.Wrap(err, "failed to request access tokens")
		s.obs.Report(ctx, wrappedError)
		return nil, time.Time{}, wrappedError
	}

	var expiration time.Time
	if sit.ExpiresAt != nil {
		expiration = *sit.ExpiresAt
	}

	return sit, expiration, err
}

func globalIDToRepositoryID(globalID types.GlobalID) (int64, error) {
	t, id, err := graphqlid.Decode(globalID.String())
	if err != nil {
		return 0, errors.Wrap(err, "failed to decode GlobalID")
	}

	if t != "Repository" {
		msg := fmt.Sprintf("Unexpected global id type %s, expected Repository", t)
		return 0, kvperrors.With(msg, kvp.String("graphql.operation.name", "globalIDToRepositoryID"))
	}

	return strconv.ParseInt(id, 10, 64)
}

// Although we need a way to resolve a global id to an installation.
// The REST API doesn't support the global id, and the GraphQL API
// doesn't support creating an installation token.
func (s *service) getDatabaseIDFromGlobalID(globalID types.GlobalID) (int64, error) {
	return globalIDToRepositoryID(globalID)
}

// appendURL takes a path that will be appended to the base URL. The base URL
// may have a prefix, such as /v3/api/, which this method should not clobber.
func (s *service) appendURL(path string) (string, error) {

	// Go has some interesting, undersireable beahviors with leading slashes.
	// The best way to see the issue is to look at is a demo, and be aware of
	// the fact that on enterprise, the url stored in s.base contains a path
	// (/v3/api/) that we must append to. To get the append behavior that we
	// desire, we need to ensure two things:
	// - Ensure that our path prefix for enterprise has a terminating slash.
	//   (e.g. /v3/api would not do).
	// - Ensure that any path being a)ppended does not lead with a slash.

	// Demonstration of the problem: https://go.dev/play/p/5LCH7FHIGnk

	// Tangential, but worth mentioning. Go does add a JoinPath API to net/url
	// in 1.18, which would be somewhat more ergonomic here than using Parse.
	// Alas.

	path = strings.TrimLeft(path, "/")
	reqURL, err := s.base.Parse(path)
	if err != nil {
		return "", err
	}

	return reqURL.String(), nil
}

func (s *service) withDefaultOpts(validator httpclient.ResponseValidator, options ...launchhttp.RequestOption) []httpclient.DoOption {
	opts := []httpclient.DoOption{
		httpclient.WithBreaker(s.breaker),
		httpclient.WithRetries(validator),
		httpclient.WithRequestErrorProcessor(errorProcessor),
		httpclient.WithRequestOptions(options...),
		httpclient.WithRequestOptions(
			launchhttp.WithHeaders(map[string]string{
				"User-Agent": useragent.GetUserAgent(s.env.String()),
				"Accept":     mediaTypeIntegrationPreview,
			}),
			func(req *http.Request) error {
				mu.ForwardRequestID(req)
				return nil
			},
		),
	}

	return opts
}

func errorProcessor(err error) error {
	// Don't retry on timeout. We want to avoid further increasing load when the access tokens endpoint when it is slow.
	// And retries can cause Launch to hit secondary rate limits across installations.
	if strings.Contains(err.Error(), "timeout awaiting response headers") {
		return backoff.Permanent(err)
	}

	return err
}
